      "id": "SV-001",
      "title": "Replit deployment types",
      "url": "https://docs.replit.com/features/publishing/deployment-types",
      "reference": "turn2view4",
      "availability": "page_text_retrieved",
      "locator": "lines 225-264",
      "excerpt": "One dedicated server that never sleeps",
      "verified_notes": "Autoscale can reach zero instances when idle. Reserved VM supports web-server or background-worker configurations; Scheduled runs a timed command then stops. These establish available deployment options, not proof that Valo's proposed queue survives restart.",
      "implementation_constraint": "Use a real durable queue and demonstrate worker restart behavior. Do not rely on a request-local timer or memory queue. Do not purchase or deploy paid resources without authorization.",
